UPDATE expense_records
SET payment_account_id = #{paymentAccountId}, amount = #{amount}, note = #{note},
    occurred_at = #{occurredAt}, updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT * FROM expense_records
WHERE family_group_id = #{familyGroupId}

    AND payment_account_id = #{paymentAccountId}


    AND author_member_id = #{authorMemberId}


    AND occurred_at >= #{monthStart} AND occurred_at < #{monthEndExclusive}

ORDER BY occurred_at DESC

